}

function compare(a: Order, b: Order, key: SortKey): number {
  switch (key) {
    case "id":
      return a.id.localeCompare(b.id)
    case "customer":
      return a.customer.localeCompare(b.customer)
    case "date":
      return a.date.getTime() - b.date.getTime()
    case "status":
      return a.status.localeCompare(b.status)
    case "amount":
