function getPageItems(page: number, total: number): Array<number | "gap"> {
  if (total <= 7) return Array.from({ length: total }, (_, i) => i + 1)
  const items: Array<number | "gap"> = [1]
  const start = Math.max(2, page - 1)
  const end = Math.min(total - 1, page + 1)
  if (start > 2) items.push("gap")
  for (let p = start; p <= end; p++) items.push(p)
  if (end < total - 1) items.push("gap")
  items.push(total)
  return items
}

interface SortHeadProps {
  label: string
  sortKey: SortKey
  active: SortKey
  dir: SortDir
  onSort: (key: SortKey) => void
  align?: "left" | "right"
  className?: string
}

function SortHead({
  label,
  sortKey,
  active,
  dir,
  onSort,
  align = "left",
  className,
}: SortHeadProps) {
  const isActive = active === sortKey
  const ariaSort: React.AriaAttributes["aria-sort"] = isActive
    ? dir === "asc"
      ? "ascending"
      : "descending"
    : "none"
  const Icon = isActive
    ? dir === "asc"
      ? ArrowUpIcon
      : ArrowDownIcon
    : ArrowUpDownIcon

  return (
    <TableHead aria-sort={ariaSort} className={className}>
      <Button
        variant="ghost"
        size="sm"
        onClick={() => onSort(sortKey)}
        className={cn(
          "-mx-2 h-8 px-2 font-medium",
          align === "right" && "ml-auto flex"
        )}
      >
        {label}
        <Icon
          aria-hidden="true"
          className={cn("size-3.5", !isActive && "text-muted-foreground")}
        />
        <span className="sr-only">
          {isActive
            ? `, sorted ${dir === "asc" ? "ascending" : "descending"}. Activate to reverse.`
            : ", not sorted. Activate to sort ascending."}
        </span>
      </Button>
    </TableHead>
  )
}

