      setSortKey(key)
      setSortDir(key === "amount" || key === "date" ? "desc" : "asc")
    }
    setPage(1)
  }

  function resetFilters() {
    setStatus("all")
    setRange(undefined)
    setQuery("")
    setPage(1)
  }

  const rangeLabel = range?.from
    ? range.to
      ? `${format(range.from, "MMM d, yyyy")} – ${format(range.to, "MMM d, yyyy")}`
      : format(range.from, "MMM d, yyyy")
    : "Pick a date range"

  const pageItems = getPageItems(currentPage, totalPages)

  return (
    <main className="min-h-screen bg-muted/30 px-4 py-6 sm:px-6 sm:py-10">
      <div className="mx-auto w-full max-w-6xl">
        <Card className="gap-4">
          <CardHeader>
            <CardTitle className="text-xl">
              <h1>Orders</h1>
            </CardTitle>
            <CardDescription>
              Review recent customer orders, filter by status or date, and sort
              by any column.
            </CardDescription>
          </CardHeader>

          <CardContent className="flex flex-col gap-4">
            {/* Filters row */}
            <div
              role="search"
              aria-label="Filter orders"
              className="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"
            >
              <div className="-mx-1 overflow-x-auto px-1 py-1">
                <ToggleGroup
                  type="single"
                  variant="outline"
                  spacing={0}
                  value={status}
                  onValueChange={(v) => {
                    if (!v) return
                    setStatus(v as StatusFilter)
                    setPage(1)
                  }}
                  aria-label="Filter by status"
                >
                  {STATUS_FILTERS.map((f) => (
                    <ToggleGroupItem
                      key={f.value}
                      value={f.value}
                      aria-label={`${f.label} orders`}
                    >
                      {f.label}
                    </ToggleGroupItem>
                  ))}
                </ToggleGroup>
              </div>

              <div className="flex flex-col gap-3 sm:flex-row sm:items-center">
                <Popover open={rangeOpen} onOpenChange={setRangeOpen}>
                  <PopoverTrigger asChild>
                    <Button
                      variant="outline"
                      data-empty={!range?.from}
                      aria-label={
                        range?.from
                          ? `Date range: ${rangeLabel}. Change date range`
                          : "Filter by date range"
                      }
                      className="w-full justify-start font-normal data-[empty=true]:text-muted-foreground sm:w-[270px]"
                    >
                      <CalendarIcon aria-hidden="true" />
                      <span className="truncate">{rangeLabel}</span>
                    </Button>
                  </PopoverTrigger>
                  <PopoverContent align="end" className="w-auto p-0">
                    <Calendar
                      mode="range"
                      numberOfMonths={1}
                      defaultMonth={range?.from ?? ANCHOR}
                      selected={range}
                      onSelect={(r) => {
                        setRange(r)
                        setPage(1)
                      }}
                      disabled={{ after: ANCHOR }}
                    />
                    <div className="flex items-center justify-between gap-2 border-t p-2">
                      <Button
                        variant="ghost"
                        size="sm"
                        disabled={!range}
                        onClick={() => {
                          setRange(undefined)
                          setPage(1)
                        }}
                      >
                        Clear
                      </Button>
                      <Button size="sm" onClick={() => setRangeOpen(false)}>
                        Done
                      </Button>
                    </div>
                  </PopoverContent>
                </Popover>

                <InputGroup className="sm:w-64">
                  <InputGroupAddon>
                    <SearchIcon aria-hidden="true" />
                  </InputGroupAddon>
                  <InputGroupInput
                    type="search"
                    inputMode="search"
                    placeholder="Search customer or order ID"
                    aria-label="Search orders by customer, email or order ID"
                    value={query}
                    onChange={(e) => {
                      setQuery(e.target.value)
                      setPage(1)
                    }}
                    className="[&::-webkit-search-cancel-button]:hidden"
                  />
                  {query && (
                    <InputGroupAddon align="inline-end">
                      <InputGroupButton
                        size="icon-xs"
                        aria-label="Clear search"
                        onClick={() => {
                          setQuery("")
                          setPage(1)
                        }}
                      >
                        <XIcon aria-hidden="true" />
                      </InputGroupButton>
                    </InputGroupAddon>
                  )}
                </InputGroup>
              </div>
            </div>

            <div className="flex min-h-8 items-center justify-between gap-2 text-sm text-muted-foreground">
              <p aria-live="polite" role="status">
                {sorted.length === 0
                  ? "No orders match your filters"
                  : `${sorted.length} ${sorted.length === 1 ? "order" : "orders"}`}
              </p>
              {hasFilters && (
                <Button variant="ghost" size="sm" onClick={resetFilters}>
                  <XIcon aria-hidden="true" />
                  Reset filters
                </Button>
              )}
            </div>

            {/* Table */}
            <div className="rounded-md border">
              <Table>
                <TableHeader className="bg-muted/50">
                  <TableRow className="hover:bg-transparent">
                    <SortHead
                      label="Order"
                      sortKey="id"
                      active={sortKey}
                      dir={sortDir}
                      onSort={handleSort}
                      className="pl-4"
                    />
                    <SortHead
                      label="Customer"
                      sortKey="customer"
                      active={sortKey}
                      dir={sortDir}
                      onSort={handleSort}
                    />
                    <SortHead
                      label="Date"
                      sortKey="date"
                      active={sortKey}
                      dir={sortDir}
                      onSort={handleSort}
                    />
                    <SortHead
                      label="Status"
                      sortKey="status"
                      active={sortKey}
                      dir={sortDir}
                      onSort={handleSort}
                    />
                    <SortHead
                      label="Amount"
                      sortKey="amount"
                      active={sortKey}
                      dir={sortDir}
                      onSort={handleSort}
                      align="right"
                      className="pr-4"
                    />
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {rows.map((o) => (
                    <TableRow key={o.id}>
                      <TableCell className="pl-4 font-mono text-xs">
                        {o.id}
                      </TableCell>
                      <TableCell>
                        <div className="flex flex-col">
                          <span className="font-medium">{o.customer}</span>
                          <span className="text-xs text-muted-foreground">
                            {o.email}
                          </span>
                        </div>
                      </TableCell>
                      <TableCell className="text-muted-foreground">
                        <time dateTime={format(o.date, "yyyy-MM-dd")}>
                          {format(o.date, "MMM d, yyyy")}
                        </time>
                      </TableCell>
                      <TableCell>
                        <Badge
                          variant="outline"
                          className={STATUS_STYLES[o.status]}
                        >
                          {o.status}
                        </Badge>
                      </TableCell>
                      <TableCell className="pr-4 text-right font-medium tabular-nums">
                        {currency.format(o.amount)}
                      </TableCell>
                    </TableRow>
                  ))}
                </TableBody>
              </Table>

              {rows.length === 0 && (
                <Empty className="border-t">
                  <EmptyHeader>
                    <EmptyMedia variant="icon">
                      <SearchXIcon aria-hidden="true" />
                    </EmptyMedia>
                    <EmptyTitle>No orders found</EmptyTitle>
                    <EmptyDescription>
                      Try a different search term, widen the date range, or
                      choose another status.
                    </EmptyDescription>
                  </EmptyHeader>
                  <Button variant="outline" size="sm" onClick={resetFilters}>
                    Reset filters
                  </Button>
                </Empty>
              )}
            </div>
          </CardContent>

          <CardFooter className="flex flex-col gap-4 lg:flex-row lg:items-center lg:justify-between">
            <div className="flex w-full items-center justify-between gap-4 lg:w-auto lg:justify-start">
              <p className="text-sm text-muted-foreground">
                Showing{" "}
                <span className="font-medium text-foreground tabular-nums">
                  {firstShown}–{lastShown}
                </span>{" "}
                of{" "}
                <span className="font-medium text-foreground tabular-nums">
                  {sorted.length}
                </span>
              </p>
              <div className="flex items-center gap-2">
                <span
                  id="page-size-label"
                  className="text-sm text-muted-foreground"
                >
                  Rows
                </span>
                <Select
                  value={pageSize}
                  onValueChange={(v) => {
                    setPageSize(v)
                    setPage(1)
                  }}
                >
                  <SelectTrigger
                    size="sm"
                    className="w-[72px]"
                    aria-labelledby="page-size-label"
                  >
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {PAGE_SIZES.map((s) => (
                      <SelectItem key={s} value={s}>
                        {s}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <nav aria-label="Pagination" className="max-w-full">
              <ul className="flex items-center gap-1">
                <li className="hidden sm:block">
                  <Button
                    variant="outline"
                    size="icon-sm"
                    aria-label="Go to first page"
                    disabled={currentPage === 1}
                    onClick={() => setPage(1)}
                  >
                    <ChevronsLeftIcon aria-hidden="true" />
                  </Button>
                </li>
                <li>
                  <Button
                    variant="outline"
                    size="icon-sm"
                    aria-label="Go to previous page"
                    disabled={currentPage === 1}
                    onClick={() => setPage(currentPage - 1)}
                  >
                    <ChevronLeftIcon aria-hidden="true" />
                  </Button>
                </li>

                {/* Compact indicator on small screens */}
                <li className="px-2 text-sm text-muted-foreground tabular-nums sm:hidden">
                  Page {currentPage} of {totalPages}
                </li>

                {pageItems.map((item, idx) =>
                  item === "gap" ? (
                    <li
                      key={`gap-${idx}`}
                      aria-hidden="true"
                      className="hidden px-1 text-muted-foreground sm:block"
                    >
                      …
                    </li>
                  ) : (
                    <li key={item} className="hidden sm:block">
                      <Button
                        variant={item === currentPage ? "default" : "ghost"}
                        size="icon-sm"
                        aria-label={`Go to page ${item}`}
                        aria-current={item === currentPage ? "page" : undefined}
                        onClick={() => setPage(item)}
                        className="tabular-nums"
                      >
                        {item}
                      </Button>
                    </li>
                  )
                )}

                <li>
                  <Button
                    variant="outline"
                    size="icon-sm"
                    aria-label="Go to next page"
                    disabled={currentPage === totalPages}
                    onClick={() => setPage(currentPage + 1)}
                  >
                    <ChevronRightIcon aria-hidden="true" />
                  </Button>
                </li>
                <li className="hidden sm:block">
                  <Button
                    variant="outline"
                    size="icon-sm"
                    aria-label="Go to last page"
                    disabled={currentPage === totalPages}
                    onClick={() => setPage(totalPages)}
                  >
                    <ChevronsRightIcon aria-hidden="true" />
                  </Button>
                </li>
              </ul>
            </nav>
          </CardFooter>
        </Card>
      </div>
    </main>
  )
}
